/*
 * Pretendard is imported here, in the entry, rather than only from the UI
 * barrel.
 *
 * The barrel lives behind `import('./bootstrap')`, which does not run until
 * the player clicks start — so the emitted index.html carried no stylesheet at
 * all and every word of the boot screen rendered in the system UI font, then
 * the entire interface changed typeface once the bundle landed. Importing from
 * the entry puts the @font-face rules in the initial CSS, so the first frame
 * and the game are the same typeface.
 */
import 'pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css'

let applicationLoadStarted = false
let applicationLoadScheduled = false

const staticTitle = document.getElementById('stillseen-static-title')
const staticStart = document.getElementById('stillseen-static-start')
const staticLoading = document.getElementById('stillseen-static-loading')

function showBootstrapError(error: unknown): void {
  if (window.__STILLSEEN_SHOW_STARTUP_ERROR__) {
    console.error('STILLSEEN application bootstrap failed.', error)
    window.__STILLSEEN_SHOW_STARTUP_ERROR__(
      '게임 화면을 불러오지 못했습니다.',
      '연결을 확인한 뒤 다시 시도해 주세요.',
    )
    return
  }
  const message = document.getElementById('stillseen-static-message')
  const detail = document.getElementById('stillseen-static-loading-detail')
  const retry = document.getElementById('stillseen-static-retry')
  const loader = document.querySelector<HTMLElement>('.stillseen-static-loader')
  console.error('STILLSEEN application bootstrap failed.', error)
  if (detail) detail.textContent = '게임 화면을 불러오지 못했습니다.'
  if (message) {
    message.textContent = '연결을 확인한 뒤 다시 시도해 주세요.'
    message.hidden = false
  }
  if (loader) loader.hidden = true
  if (staticLoading) staticLoading.setAttribute('aria-busy', 'false')
  if (retry instanceof HTMLButtonElement) {
    retry.hidden = false
    retry.addEventListener('click', () => window.location.reload(), {
      once: true,
    })
    retry.focus()
  }
}

function loadApplication(): void {
  if (applicationLoadStarted) return
  applicationLoadStarted = true
  void import('./bootstrap')
    .then(({ mountApplication }) =>
      mountApplication({
        autoStart: true,
      }),
    )
    .catch((error: unknown) => showBootstrapError(error))
}

function loadAfterLoadingScreenPaints(): void {
  // The first callback is followed by a paint; loading starts on the next
  // frame, so the player sees 0% before React, Three.js, or the game shell.
  requestAnimationFrame(() => requestAnimationFrame(loadApplication))
}

function primeAudioFromGesture(): void {
  if (window.__STILLSEEN_PRIMED_AUDIO_CONTEXT__) return
  const AudioContextConstructor = globalThis.AudioContext
  if (typeof AudioContextConstructor !== 'function') return
  try {
    const context = new AudioContextConstructor()
    window.__STILLSEEN_PRIMED_AUDIO_CONTEXT__ = context
    void context.resume().catch(() => undefined)
  } catch {
    // AudioEngine retains its synthesized/no-audio fallbacks.
  }
}

function detachStartListeners(): void {
  staticStart?.removeEventListener('click', handleStartClick)
}

function beginLoading(): void {
  if (applicationLoadScheduled) return
  applicationLoadScheduled = true
  primeAudioFromGesture()
  detachStartListeners()
  if (staticTitle) staticTitle.dataset.state = 'loading'
  if (staticStart instanceof HTMLButtonElement) staticStart.disabled = true
  if (staticLoading) {
    staticLoading.hidden = false
    staticLoading.focus({ preventScroll: true })
  }
  loadAfterLoadingScreenPaints()
}

function handleCapturedStart(): void {
  beginLoading()
}

function handleStartClick(): void {
  beginLoading()
}

if (window.__STILLSEEN_START_REQUESTED__) {
  beginLoading()
} else {
  window.addEventListener('stillseen:start', handleCapturedStart, {
    once: true,
  })
  staticStart?.addEventListener('click', handleStartClick)
}

export {}
